{
  "schemaVersion": "0.2",
  "slug": "slider",
  "name": "Slider",
  "status": "experimental",
  "purpose": "Selects a numeric value from a range using a native input. Supports step, marks, and an optional dual-thumb pair.",
  "scenarios": [
    "Set a volume level",
    "Choose a price range",
    "Adjust a rating threshold"
  ],
  "props": {
    "value": {
      "type": "number",
      "required": true,
      "description": "Current value, or a [min, max] pair for a dual-thumb range."
    },
    "min": {
      "type": "number",
      "required": false,
      "description": "Minimum value.",
      "default": 0
    },
    "max": {
      "type": "number",
      "required": false,
      "description": "Maximum value.",
      "default": 100
    },
    "step": {
      "type": "number",
      "required": false,
      "description": "Native range step. Defaults to 1.",
      "default": 1
    },
    "marks": {
      "type": "string",
      "required": false,
      "description": "Optional tick values rendered under the track (number[])."
    },
    "disabled": {
      "type": "boolean",
      "required": false,
      "description": "Prevents pointer and keyboard changes.",
      "default": false
    },
    "onChange": {
      "type": "event",
      "required": true,
      "description": "Called when the value changes."
    },
    "label": {
      "type": "string",
      "required": false,
      "description": "Accessible label for the slider."
    },
    "className": {
      "type": "string",
      "required": false,
      "description": "Additional CSS classes."
    }
  },
  "variants": [],
  "states": [
    {
      "name": "default",
      "description": "Single-thumb slider rendered."
    },
    {
      "name": "range",
      "description": "Dual-thumb range pair."
    },
    {
      "name": "disabled",
      "description": "Interaction blocked."
    }
  ],
  "composition": {
    "allowedParents": [
      "form",
      "page",
      "card"
    ],
    "allowedChildren": [],
    "requiredContext": []
  },
  "antiPatterns": [
    "Do not use for precise values without a text input fallback.",
    "Do not omit a label."
  ],
  "a11y": {
    "role": "slider",
    "keyboard": [
      "Arrow keys change value"
    ],
    "focus": "Slider is focusable.",
    "labeling": "Label or aria-label provides the accessible name.",
    "wcag": [
      "4.1.2",
      "2.1.1"
    ]
  },
  "responsive": {
    "strategy": "Full width input range.",
    "breakpoints": {
      "compact": "Full width.",
      "medium": "Full width.",
      "large": "Full width."
    }
  },
  "platforms": {
    "web": "supported",
    "react": "supported",
    "vue": "supported"
  },
  "rtl": {
    "supported": true,
    "strategy": "Native input range inherits direction.",
    "mirroredValues": []
  },
  "dataAi": {
    "role": "slider",
    "states": [
      "default",
      "range",
      "disabled"
    ],
    "intents": [
      "adjust-value"
    ]
  }
}

import './styles.css'

export type SliderValue = number | readonly [number, number]

export interface SliderProps {
  value: SliderValue
  min?: number
  max?: number
  step?: number
  marks?: number[]
  disabled?: boolean
  onChange: (value: SliderValue) => void
  label?: string
  className?: string
}

function isRange(value: SliderValue): value is readonly [number, number] {
  return Array.isArray(value)
}

export function Slider({
  value,
  min = 0,
  max = 100,
  step = 1,
  marks,
  disabled = false,
  onChange,
  label,
  className,
}: SliderProps) {
  const classes = ['cu-slider', disabled ? 'cu-slider--disabled' : '', className].filter(Boolean).join(' ')
  const range = isRange(value)

  return (
    <div
      className={classes}
      data-ai-role="slider"
      data-ai-state={disabled ? 'disabled' : range ? 'range' : 'default'}
      data-ai-intent="adjust-value"
    >
      {label ? <label className="cu-slider__label">{label}</label> : null}
      {range ? (
        <div className="cu-slider__inputs">
          <input
            aria-label={label ? `${label} minimum` : 'Minimum'}
            className="cu-slider__input"
            disabled={disabled}
            max={value[1]}
            min={min}
            onChange={(event) => onChange([Number(event.currentTarget.value), value[1]])}
            step={step}
            type="range"
            value={value[0]}
          />
          <input
            aria-label={label ? `${label} maximum` : 'Maximum'}
            className="cu-slider__input"
            disabled={disabled}
            max={max}
            min={value[0]}
            onChange={(event) => onChange([value[0], Number(event.currentTarget.value)])}
            step={step}
            type="range"
            value={value[1]}
          />
        </div>
      ) : (
        <input
          aria-label={label}
          className="cu-slider__input"
          disabled={disabled}
          max={max}
          min={min}
          onChange={(event) => onChange(Number(event.currentTarget.value))}
          step={step}
          type="range"
          value={value}
        />
      )}
      {marks && marks.length > 0 ? (
        <div className="cu-slider__marks">
          {marks.map((mark) => (
            <span
              className="cu-slider__mark"
              key={mark}
              style={{ insetInlineStart: `${((mark - min) / Math.max(max - min, 1)) * 100}%` }}
            >
              {mark}
            </span>
          ))}
        </div>
      ) : null}
    </div>
  )
}

.cu-slider {
  display: grid;
  gap: var(--cu-space-1);
}

.cu-slider__label {
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--cu-color-fg-default);
}

.cu-slider__inputs {
  display: grid;
  gap: var(--cu-space-1);
}

.cu-slider__input {
  inline-size: 100%;
  accent-color: var(--cu-color-palette-brand);
  cursor: pointer;
}

.cu-slider__input:focus-visible {
  outline: 3px solid var(--cu-color-palette-brand);
  outline-offset: 3px;
  border-radius: var(--cu-radius-sm);
}

.cu-slider__input:disabled {
  cursor: not-allowed;
  opacity: 0.55;
}

.cu-slider__marks {
  position: relative;
  min-block-size: 1.25rem;
}

.cu-slider__mark {
  position: absolute;
  transform: translateX(-50%);
  font-size: 0.75rem;
  color: color-mix(in srgb, var(--cu-color-fg-default) 72%, transparent);
}

[dir='rtl'] .cu-slider__mark {
  transform: translateX(50%);
}
